#include <iostream>
using namespace std;
const int N = 510;
int a[N], b[N];
long long ans;
void solve(int l, int r, int depth) {
    if (l > r) return;
    int mid = l;
    for (int i = l + 1; i <= r; i++) {
        if (a[i] < a[mid]) mid = i;
    }
    ans += (long long)b[mid] * depth;
    solve(l, mid - 1, depth + 1);
    solve(mid + 1, r, depth + 1);
}
int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) cin >> b[i];
    ans = 0;
    solve(1, n, 1);
    cout << ans << endl;
    return 0;
}

