#include <iostream>
#include <algorithm>
using namespace std;
const int N = 15;
int d[N][2];
int ans, n;

void dfs(int step) {
    if (step == 1) {
        ans = max(ans, d[0][1]);
        return;
    }
    int old[N][2];
    for (int i = 0; i < step; i++) {
        old[i][0] = d[i][0];
        old[i][1] = d[i][1];
    }
    for (int i = 0; i < step - 1; i++) {
        int a = d[i][0], b = d[i + 1][0];
        int c = d[i][1] + d[i + 1][1] + a * b;
        d[i][0] = a + b;
        d[i][1] = c;
        for (int j = i + 1; j < step - 1; j++) {
            d[j][0] = old[j + 1][0];
            d[j][1] = old[j + 1][1];
        }
        dfs(step - 1);
        for (int j = 0; j < step; j++) {
            d[j][0] = old[j][0];
            d[j][1] = old[j][1];
        }
    }
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) cin >> d[i][0] >> d[i][1];
    ans = 0;
    dfs(n);
    cout << ans << endl;
    return 0;
}

#include <iostream>
using namespace std;
const int N = 1000010;
int prime[N], cnt;
bool st[N];
int f[N], g[N], num[N];

int main() {
    int n;
    cin >> n;
    f[1] = 1; g[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!st[i]) {
            prime[cnt++] = i;
            f[i] = 2;
            g[i] = 1 + i;
            num[i] = 1;
        }
        for (int j = 0; j < cnt && i * prime[j] <= n; j++) {
            st[i * prime[j]] = true;
            if (i % prime[j] == 0) {
                num[i * prime[j]] = num[i] + 1;
                f[i * prime[j]] = f[i] / (num[i] + 1) * (num[i] + 2);
                g[i * prime[j]] = g[i] * prime[j] + 1;
                break;
            } else {
                num[i * prime[j]] = 1;
                f[i * prime[j]] = f[i] * 2;
                g[i * prime[j]] = g[i] * (1 + prime[j]);
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cout << i << ": f=" << f[i] << " g=" << g[i] << endl;
    }
    return 0;
}
